interface TabItemProps {
  icon: React.ReactNode;
  label: string;
  isActive: boolean;
  onPress: () => void;
}

function TabItem({ icon, label, isActive, onPress }: TabItemProps) {
  const color = isActive ? "#FFF0F5" : "#FF99BC";

  return (
    <TouchableOpacity
      onPress={onPress}
      className="items-center justify-center px-2 py-1 gap-0.5"
      activeOpacity={0.7}
    >
      {icon}
      <Text
        className="text-[10px] font-medium text-center tracking-tight"
        style={{ color }}
      >
        {label}
      </Text>
    </TouchableOpacity>
  );
}

export function BottomNavigation({
  activeTab,
  onTabPress,
}: BottomNavigationProps) {
  const insets = useSafeAreaInsets();
  const { t } = useLanguage();
  const bottomPadding = Platform.OS === "ios" ? Math.max(insets.bottom, 8) : 8;

  return (
    <View className="bg-home-nav-bg">
      <View className="flex-row justify-between items-center px-6 py-4">
        {/* Home */}
        <TabItem
          icon={
            <HouseIcon color={activeTab === "home" ? "#FFF0F5" : "#FF99BC"} />
          }
          label={t("nav.home")}
          isActive={activeTab === "home"}
          onPress={() => onTabPress("home")}
        />

        {/* Calendar */}
        <TabItem
          icon={
            <CalendarIcon active={activeTab === "calendar"} color={activeTab === "calendar" ? "#FFF0F5" : "#FF99BC"} />
          }
          label={t("nav.calendar")}
          isActive={activeTab === "calendar"}
          onPress={() => onTabPress("calendar")}
        />

        {/* Center Add Button */}
        <TouchableOpacity
          onPress={() => onTabPress("add")}
          className="-mt-6"
          activeOpacity={0.8}
        >
          <Svg width={60} height={60} viewBox="0 0 60 60" fill="none">
            <Path d="M0 30C0 13.4315 13.4315 0 30 0C46.5685 0 60 13.4315 60 30C60 46.5685 46.5685 60 30 60C13.4315 60 0 46.5685 0 30Z" fill="#FF669A" />
            <Path d="M44.0625 30C44.0625 30.4476 43.8847 30.8768 43.5682 31.1932C43.2518 31.5097 42.8226 31.6875 42.375 31.6875H31.6875V42.375C31.6875 42.8226 31.5097 43.2518 31.1932 43.5682C30.8768 43.8847 30.4476 44.0625 30 44.0625C29.5524 44.0625 29.1232 43.8847 28.8068 43.5682C28.4903 43.2518 28.3125 42.8226 28.3125 42.375V31.6875H17.625C17.1774 31.6875 16.7482 31.5097 16.4318 31.1932C16.1153 30.8768 15.9375 30.4476 15.9375 30C15.9375 29.5524 16.1153 29.1232 16.4318 28.8068C16.7482 28.4903 17.1774 28.3125 17.625 28.3125H28.3125V17.625C28.3125 17.1774 28.4903 16.7482 28.8068 16.4318C29.1232 16.1153 29.5524 15.9375 30 15.9375C30.4476 15.9375 30.8768 16.1153 31.1932 16.4318C31.5097 16.7482 31.6875 17.1774 31.6875 17.625V28.3125H42.375C42.8226 28.3125 43.2518 28.4903 43.5682 28.8068C43.8847 29.1232 44.0625 29.5524 44.0625 30Z" fill="white" />
          </Svg>
        </TouchableOpacity>

        {/* Chat */}
        <TabItem
          icon={
            <ChatIcon
              filled={activeTab === "chat"}
              color={activeTab === "chat" ? "#FFF0F5" : "#FF99BC"}
            />
          }
          label={t("nav.chat")}
          isActive={activeTab === "chat"}
          onPress={() => onTabPress("chat")}
        />

        {/* Settings */}
        <TabItem
          icon={
            <SettingsIcon
              active={activeTab === "settings"}
              color={activeTab === "settings" ? "#FFF0F5" : "#FF99BC"}
            />
          }
          label={t("nav.settings")}
          isActive={activeTab === "settings"}
          onPress={() => onTabPress("settings")}
        />
      </View>

      {/* Home Indicator */}
      <View
        className="items-center justify-end bg-home-nav-bg"
        style={{ paddingBottom: bottomPadding, paddingTop: 4 }}
      />
    </View>
  );
}
